  "CAP_Theorem": {
    "Explanation": "The CAP theorem states that in a distributed system, it is impossible to simultaneously guarantee all three of the following properties: Consistency, Availability, and Partition Tolerance. A system can only achieve at most two out of these three guarantees.",
    "Properties": {
      "Consistency": "Every read receives the most recent write or an error.",
      "Availability": "Every request receives a response, without guarantee that it contains the most recent write.",
      "Partition Tolerance": "The system continues to operate despite arbitrary partitioning due to network failures."
    },
    "Examples": [
      {
        "System": "Couchbase",
        "Guarantees": ["Consistency", "Availability"],
        "Sacrifice": "Partition Tolerance",
        "Explanation": "Couchbase can be configured to prioritize consistency and availability by replicating data across nodes. However, in the event of a network partition, it may not be able to maintain both consistency and availability."
      },
      {
        "System": "Apache Cassandra",
        "Guarantees": ["Availability", "Partition Tolerance"],
        "Sacrifice": "Consistency",
        "Explanation": "Cassandra prioritizes availability and partition tolerance. It allows for eventual consistency, meaning that data may not be consistent across all nodes immediately after a write but will eventually become consistent."
      },
      {
        "System": "MongoDB (with replica sets)",
        "Guarantees": ["Consistency", "Partition Tolerance"],
        "Sacrifice": "Availability",
        "Explanation": "MongoDB can be configured to prioritize consistency and partition tolerance. During a network partition, it may become unavailable to ensure that all nodes have consistent data."
      }
    ]
  }
