using System;
using System.Text.RegularExpressions;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace EmailValidator.Tests
{
    [TestClass]
    public class EmailValidatorTests
    {
        [TestMethod]
        public void IsValidEmail_ValidEmail_ReturnsTrue()
        {
            // Arrange
            var validator = new EmailValidator();
            string validEmail = "test.user@example.com";

            // Act
            bool result = validator.IsValidEmail(validEmail);

            // Assert
            Assert.IsTrue(result);
        }

        [TestMethod]
        public void IsValidEmail_InvalidEmail_ReturnsFalse()
        {
            // Arrange
            var validator = new EmailValidator();
            string invalidEmail = "invalid-email@";

            // Act
            bool result = validator.IsValidEmail(invalidEmail);

            // Assert
            Assert.IsFalse(result);
        }

        [TestMethod]
        public void IsValidEmail_NullEmail_ReturnsFalse()
        {
            // Arrange
            var validator = new EmailValidator();
            string nullEmail = null;

            // Act
            bool result = validator.IsValidEmail(nullEmail);

            // Assert
            Assert.IsFalse(result);
        }

        [TestMethod]
        public void IsValidEmail_EmptyEmail_ReturnsFalse()
        {
            // Arrange
            var validator = new EmailValidator();
            string emptyEmail = "";

            // Act
            bool result = validator.IsValidEmail(emptyEmail);

            // Assert
            Assert.IsFalse(result);
        }
    }

    public class EmailValidator
    {
        private readonly Regex _emailRegex = new Regex(
            @"^[\w!#$%&'*+/=?`{|}~^-]+(\.[\w!#$%&'*+/=?`{|}~^-]+)*@([a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}$");

        public bool IsValidEmail(string email)
        {
            if (string.IsNullOrWhiteSpace(email))
                return false;

            return _emailRegex.IsMatch(email);
        }
    }
}
```

