- **EmailValidator Class**: Contains the `IsValidEmail` method that performs the validation.
- **Unit Tests**: Uses MSTest to test various email inputs including valid, invalid, null, and empty strings.

### Notes:
- This regex is not 100% RFC-compliant (which is very complex), but it's suitable for most real-world applications.
- Make sure to install the MSTest framework and reference it in your test project."

"function mergeTwoLists(l1, l2) {
    // Create a dummy node to act as the starting point of the merged list
    let dummy = new ListNode(0);
    // Tail pointer to build the new list
    let tail = dummy;

    // Traverse both lists
    while (l1 !== null && l2 !== null) {
        if (l1.val < l2.val) {
            tail.next = l1;
            l1 = l1.next;
        } else {
            tail.next = l2;
            l2 = l2.next;
        }
        tail = tail.next;
    }

    // Attach the remaining elements of l1 or l2
    tail.next = l1 !== null ? l1 : l2;

    // The merged list is next to the dummy node
    return dummy.next;
}

// Definition for singly-linked list node
class ListNode {
    constructor(val, next = null) {
        this.val = val;
        this.next = next;
    }
}

